/* Fleet UI — pre-paint theme+density, smallest form. Inline in <head> of static
   pages BEFORE the stylesheet link. Full API is in theme.js. */
!function(){try{var d=document.documentElement,t=localStorage.getItem("fleet.theme")||"system",n=localStorage.getItem("fleet.density")||"comfortable";["system","light","dark","ambient","high-contrast"].indexOf(t)<0&&(t="system");"system"===t?d.removeAttribute("data-theme"):d.setAttribute("data-theme",t);"compact"===n?d.setAttribute("data-density","compact"):d.removeAttribute("data-density")}catch(e){}}();
